package com.braseiro.dnd5e;

import org.json.JSONArray;
import org.json.JSONObject;

/** Source-bound Tasha feat pack. Structured mechanics only; no autonomous character mutation. */
public final class TashaFeatCompiledRulesEngine {
    public static final String BOOK=TashaCompiledSourceRulesEngine.BOOK;
    public static final String SOURCE_FILE=TashaCompiledSourceRulesEngine.SOURCE_FILE;
    public static final String SOURCE_SHA256=TashaCompiledSourceRulesEngine.SOURCE_SHA256;
    private static final String[] NAMES={"Artificer Initiate","Chef","Crusher","Eldritch Adept","Fey Touched","Fighting Initiate","Gunner","Metamagic Adept","Piercer","Poisoner","Shadow Touched","Skill Expert","Slasher","Telekinetic","Telepathic"};
    private static final String[] PT={"Iniciado Artífice","Chef","Esmagador","Adepto Místico","Tocado pelas Fadas","Iniciado em Combate","Pistoleiro","Adepto Metamágico","Perfurador","Envenenador","Tocado pelas Sombras","Especializado em Perícia","Lacerador","Telecinético","Telepático"};
    private TashaFeatCompiledRulesEngine(){}

    public static JSONObject descriptor(){/*BR_JSON_WRAP_106*/try{return new JSONObject().put("id","tasha_feat_pack").put("book",BOOK).put("source_file",SOURCE_FILE).put("source_sha256",SOURCE_SHA256).put("feats",NAMES.length).put("resolution_mode","compiled_source_rules").put("rag_required",false).put("auto_mutation_allowed",false).put("source_bound_only",true).put("effect_pipeline_complete",false);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}

    public static synchronized JSONObject install(){/*BR_JSON_WRAP_106*/try{JSONArray ev=new JSONArray(),ct=new JSONArray();for(int i=0;i<NAMES.length;i++){String id="tasha-feat-"+slug(NAMES[i])+"-r1";String loc=SOURCE_FILE+" pp. 80-83 - "+PT[i];JSONObject basis=new JSONObject().put("source_type","reviewed_evidence").put("evidence_id",id).put("content_kind","feat").put("content_name",NAMES[i]).put("source_book",BOOK).put("source_locator",loc).put("source_sha256",SOURCE_SHA256).put("revision",1);ev.put(new JSONObject().put("evidence_id",id).put("content_kind","feat").put("content_name",NAMES[i]).put("source_book",BOOK).put("source_locator",loc).put("source_sha256",SOURCE_SHA256).put("revision",1));ct.put(new JSONObject().put("kind","feat").put("name",NAMES[i]).put("mechanics",mechanics(NAMES[i],PT[i])).put("mechanical_basis",basis));}JSONObject r=AuthorizedContentTransactionEngine.install(ev,ct);return r.put("descriptor",descriptor()).put("source_bound_records",NAMES.length);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}

    public static JSONObject readiness(){/*BR_JSON_WRAP_106*/try{int source=CompiledContentMechanicsEngine.count("feat"),effects=CompiledContentMechanicsEngine.countEffectPipelineComplete("feat");return new JSONObject().put("feats",source).put("expected_feats",NAMES.length).put("source_bound",source).put("source_bound_complete",source>=NAMES.length).put("effect_pipelines",effects).put("effect_pipeline_complete",effects>=NAMES.length).put("complete",effects>=NAMES.length).put("source_sha256",SOURCE_SHA256).put("status",effects>=NAMES.length?"effect_pipeline_complete":source>=NAMES.length?"source_bound_requires_effect_pipeline":"source_binding_incomplete");}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}

    private static JSONObject mechanics(String n,String pt){/*BR_JSON_WRAP_106*/try{JSONObject o=new JSONObject().put("resolution_mode","compiled_source_rules").put("source_bound",true).put("rag_required",false).put("auto_mutation_allowed",false).put("source_name_ptbr",pt).put("source_pages","80-83").put("source_sha256",SOURCE_SHA256);
        if(n.equals("Metamagic Adept"))return o.put("prerequisite","Spellcasting or Pact Magic").put("metamagic_options_known",2).put("sorcery_points",2).put("points_use","metamagic_only").put("recharge","long_rest").put("swap_option_on_asi_level",true);
        if(n.equals("Eldritch Adept"))return o.put("prerequisite","Spellcasting or Pact Magic").put("eldritch_invocations_known",1).put("invocation_prerequisite_policy","if invocation has prerequisite, character must be a warlock satisfying it").put("swap_on_character_level",true);
        if(n.equals("Chef"))return o.put("ability_increase_choices",new JSONArray().put("CON").put("WIS")).put("ability_increase",1).put("cook_utensils_proficiency",true).put("short_rest_meal_targets_formula","4 + proficiency_bonus").put("short_rest_extra_healing","1d8 when target spends >=1 Hit Die").put("snacks_count_formula","proficiency_bonus").put("snack_prep","1 hour work or long rest").put("snack_lifetime_hours",8).put("snack_eat_action","bonus_action").put("snack_temp_hp_formula","proficiency_bonus");
        if(n.equals("Poisoner"))return o.put("ignore_poison_resistance",true).put("apply_poison_action","bonus_action").put("poisoners_kit_proficiency",true).put("craft_time_hours",1).put("craft_cost_gp",50).put("crafted_doses_formula","proficiency_bonus").put("applied_potency_minutes",1).put("save","CON DC 14").put("failed_save_damage","2d8 poison").put("failed_save_condition","poisoned until end of target next turn");
        if(n.equals("Crusher"))return o.put("ability_increase_choices",new JSONArray().put("STR").put("CON")).put("ability_increase",1).put("once_per_turn_bludgeoning_move_ft",5).put("move_size_limit","target no more than one size larger").put("critical_effect","attacks against target have advantage until start of your next turn");
        if(n.equals("Skill Expert"))return o.put("ability_increase_choices","any").put("ability_increase",1).put("skill_proficiency_gain",1).put("expertise_gain",1);
        if(n.equals("Artificer Initiate"))return o.put("artificer_cantrips_known",1).put("artificer_level1_spells_known",1).put("spellcasting_ability","INT").put("free_level1_casts_per_long_rest",1).put("can_use_spell_slots",true).put("artisan_tool_proficiency",1).put("chosen_artisan_tool_can_be_focus_for_INT_spells",true);
        if(n.equals("Fighting Initiate"))return o.put("prerequisite","martial weapon proficiency").put("fighter_fighting_styles_known",1).put("must_choose_different_style_if_already_have_one",true).put("swap_style_on_asi_level",true);
        if(n.equals("Slasher"))return o.put("ability_increase_choices",new JSONArray().put("STR").put("DEX")).put("ability_increase",1).put("once_per_turn_slashing_speed_reduction_ft",10).put("speed_reduction_duration","until start of your next turn").put("critical_effect","target has disadvantage on attack rolls until start of your next turn");
        if(n.equals("Piercer"))return o.put("ability_increase_choices",new JSONArray().put("STR").put("DEX")).put("ability_increase",1).put("once_per_turn_reroll_one_piercing_damage_die",true).put("must_use_new_roll",true).put("critical_extra_damage_die",1);
        if(n.equals("Gunner"))return o.put("ability_increase_choices",new JSONArray().put("DEX")).put("ability_increase",1).put("firearm_proficiency",true).put("ignore_firearm_loading_property",true).put("ranged_attacks_with_hostile_within_5ft_no_disadvantage",true);
        if(n.equals("Telekinetic"))return o.put("ability_increase_choices",new JSONArray().put("INT").put("WIS").put("CHA")).put("ability_increase",1).put("mage_hand_known",true).put("mage_hand_no_verbal_or_somatic",true).put("mage_hand_can_be_invisible",true).put("mage_hand_extra_range_ft_if_already_known",30).put("telekinetic_shove_range_ft",30).put("telekinetic_shove_save","STR vs 8 + proficiency + increased ability modifier").put("telekinetic_shove_distance_ft",5);
        if(n.equals("Telepathic"))return o.put("ability_increase_choices",new JSONArray().put("INT").put("WIS").put("CHA")).put("ability_increase",1).put("telepathy_range_ft",60).put("telepathy_one_way",true).put("language_required_for_understanding",true).put("detect_thoughts_free_per_long_rest",1).put("detect_thoughts_no_components",true).put("can_use_spell_slots",true);
        if(n.equals("Fey Touched"))return o.put("ability_increase_choices",new JSONArray().put("INT").put("WIS").put("CHA")).put("ability_increase",1).put("granted_spell","Misty Step").put("additional_level1_spell_schools",new JSONArray().put("Divination").put("Enchantment")).put("each_spell_free_per_long_rest",1).put("can_use_spell_slots",true);
        if(n.equals("Shadow Touched"))return o.put("ability_increase_choices",new JSONArray().put("INT").put("WIS").put("CHA")).put("ability_increase",1).put("granted_spell","Invisibility").put("additional_level1_spell_schools",new JSONArray().put("Illusion").put("Necromancy")).put("each_spell_free_per_long_rest",1).put("can_use_spell_slots",true);
        return o;
    }catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
    private static String slug(String s){return s.toLowerCase(java.util.Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");}
}
